package com.kongye.floatball;

import android.app.Activity;
import android.content.*;
import android.content.pm.*;
import android.os.*;
import android.graphics.Color;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;

/** Dedicated input window: searchable, grouped application rows with icon/APK size/install date. */
public class AppPickerActivity extends Activity {
    private static final class Item {final AppCatalog.Entry entry;final String group,size,date;Item(AppCatalog.Entry e,String g,String s,String d){entry=e;group=g;size=s;date=d;}}
    private final ArrayList<Item> items=new ArrayList<>();private final ArrayList<Object> rows=new ArrayList<>();private final Set<String> collapsed=new HashSet<>();private final Map<String,Integer> counts=new HashMap<>();
    private EditText search;private ListView list;private BaseAdapter adapter;private String selected;private TextView confirm;
    @Override public void onCreate(Bundle state){super.onCreate(state);ThemePolicy.apply(this);setTheme(Ui.dark?R.style.AppThemeDark:R.style.AppTheme);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
        FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0x77000000);LinearLayout card=Ui.card(this);Ui.pad(card,16,10,16,14);card.setElevation(dp(12));LinearLayout titleRow=Ui.row(this);titleRow.addView(Ui.tool(this,"back","取消选择",this::finish),new LinearLayout.LayoutParams(dp(40),dp(40)));TextView heading=Ui.text(this,ruleMode()?"特定应用中的悬浮球":"选择应用",19,Ui.INK,true);Ui.pad(heading,6,0,0,0);titleRow.addView(heading,new LinearLayout.LayoutParams(0,-2,1));card.addView(titleRow);Ui.gap(card,10);search=Ui.field(this,"搜索本地应用");search.setId(R.id.app_search);search.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);card.addView(search,new LinearLayout.LayoutParams(-1,dp(44)));Ui.gap(card,8);
        list=new ListView(this);list.setDivider(null);list.setFastScrollEnabled(true);adapter=new BaseAdapter(){public int getCount(){return rows.size();}public Object getItem(int p){return rows.get(p);}public long getItemId(int p){return p;}public View getView(int position,View convert,ViewGroup parent){Object item=rows.get(position);if(item instanceof String group){LinearLayout head=Ui.row(AppPickerActivity.this);Ui.pad(head,4,14,4,8);head.addView(Ui.text(AppPickerActivity.this,group+" ("+counts.getOrDefault(group,0)+")",12,Ui.MUTED,false),new LinearLayout.LayoutParams(0,-2,1));head.addView(Ui.icon(AppPickerActivity.this,collapsed.contains(group)?"expand":"collapse",Ui.MUTED,18));head.setContentDescription("应用分组 "+group);return head;}Item app=(Item)item;LinearLayout row=Ui.row(AppPickerActivity.this);Ui.pad(row,4,10,4,10);if(app.entry.pkg.equals(selected))row.setBackground(Ui.bg(Ui.PALE,12,AppPickerActivity.this));ImageView icon=new ImageView(AppPickerActivity.this);icon.setImageDrawable(app.entry.info.loadIcon(getPackageManager()));row.addView(icon,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout titles=Ui.column(AppPickerActivity.this);Ui.pad(titles,12,0,3,0);titles.addView(Ui.text(AppPickerActivity.this,app.entry.label,16,Ui.INK,false));Ui.gap(titles,4);titles.addView(Ui.text(AppPickerActivity.this,app.size,11,Ui.MUTED,false));if(ruleMode())titles.addView(Ui.text(AppPickerActivity.this,AppBehavior.label(AppBehavior.mode(AppPickerActivity.this,app.entry.pkg)),12,Ui.GREEN,false));row.addView(titles,new LinearLayout.LayoutParams(0,-2,1));row.addView(Ui.text(AppPickerActivity.this,app.date,11,Ui.MUTED,false));row.setContentDescription(ruleMode()?"应用悬浮球状态："+app.entry.label+"："+AppBehavior.label(AppBehavior.mode(AppPickerActivity.this,app.entry.pkg)):"选择应用："+app.entry.label);return row;}};list.setAdapter(adapter);card.addView(list,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=Ui.row(this);if(ruleMode()&&!AppCatalog.hasUsage(this))card.addView(Ui.button(this,"开启使用记录访问权限",false,()->startActivity(new Intent(android.provider.Settings.ACTION_USAGE_ACCESS_SETTINGS,android.net.Uri.parse("package:"+getPackageName())))));Ui.pad(bottom,0,10,0,0);LinearLayout.LayoutParams cancelAt=new LinearLayout.LayoutParams(0,-2,1);cancelAt.rightMargin=dp(5);bottom.addView(Ui.button(this,"取消",false,this::finish),cancelAt);confirm=Ui.button(this,ruleMode()?"完成":"确定",true,()->{if(ruleMode()){finish();return;}if(selected!=null){setResult(RESULT_OK,new Intent().putExtra("selected","app:"+selected));finish();}});confirm.setEnabled(ruleMode());confirm.setAlpha(ruleMode()?1f:.45f);LinearLayout.LayoutParams confirmAt=new LinearLayout.LayoutParams(0,-2,1);confirmAt.leftMargin=dp(5);bottom.addView(confirm,confirmAt);card.addView(bottom);
        FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-1);cp.setMargins(dp(16),dp(24),dp(16),dp(16));root.addView(card,cp);setContentView(root);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{int top,insetBottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());top=bars.top;insetBottom=Math.max(bars.bottom,insets.getInsets(WindowInsets.Type.ime()).bottom);}else{top=insets.getSystemWindowInsetTop();insetBottom=insets.getSystemWindowInsetBottom();}v.setPadding(0,top,0,insetBottom);return insets;});root.setFocusableInTouchMode(true);root.requestFocus();
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){collapsed.clear();populate();}public void afterTextChanged(Editable e){}});
        String query=getIntent().getStringExtra("query");if(query!=null)search.setText(query);
        list.setOnItemClickListener((parent,view,position,id)->{Object item=rows.get(position);if(item instanceof String group){if(!collapsed.remove(group))collapsed.add(group);populate();}else{Item app=(Item)item;if(ruleMode()){chooseRule(app.entry.pkg,app.entry.label);return;}selected=app.entry.pkg;confirm.setEnabled(true);confirm.setAlpha(1f);adapter.notifyDataSetChanged();}});
        new Thread(()->{ArrayList<Item> loaded=new ArrayList<>();android.icu.text.AlphabeticIndex.ImmutableIndex<String> index=new android.icu.text.AlphabeticIndex<String>(Locale.CHINA).addLabels(Locale.ENGLISH).buildImmutableIndex();java.text.SimpleDateFormat date=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);for(AppCatalog.Entry entry:AppCatalog.all(this)){String group;char first=entry.label.isEmpty()?'#':entry.label.charAt(0);if(Character.isDigit(first))group=String.valueOf(first);else{group=index.getBucket(index.getBucketIndex(entry.label)).getLabel();if(group.length()!=1||!Character.isLetter(group.charAt(0)))group="#";}String size="—",installed="";try{ApplicationInfo info=getPackageManager().getApplicationInfo(entry.pkg,0);long bytes=new File(info.sourceDir).length();if(info.splitSourceDirs!=null)for(String split:info.splitSourceDirs)bytes+=new File(split).length();size=String.format(Locale.US,"%.2f MB",bytes/1048576d);installed=date.format(new Date(getPackageManager().getPackageInfo(entry.pkg,0).firstInstallTime));}catch(Exception ignored){}loaded.add(new Item(entry,group,size,installed));}loaded.sort((a,b)->{int g=a.group.compareTo(b.group);return g!=0?g:java.text.Collator.getInstance(Locale.CHINA).compare(a.entry.label,b.entry.label);});runOnUiThread(()->{if(!isFinishing()){items.addAll(loaded);populate();}});},"Kongye-AppList").start();
    }
    protected boolean ruleMode(){return false;}
    private void chooseRule(String pkg,String label){String[] ids={"disabled","hidden","normal"},labels={"禁用","隐身，可以操作","正常显示，可以操作"};int selected=Arrays.asList(ids).indexOf(AppBehavior.mode(this,pkg));new android.app.AlertDialog.Builder(this).setTitle(label).setSingleChoiceItems(labels,Math.max(0,selected),(d,at)->{android.content.SharedPreferences.Editor edit=Prefs.of(this).edit();if(ids[at].equals("normal"))edit.remove("app_mode_"+pkg);else edit.putString("app_mode_"+pkg,ids[at]);edit.apply();if(FloatService.instance!=null)FloatService.instance.foregroundChanged(AssistService.foregroundPackage);d.dismiss();adapter.notifyDataSetChanged();}).setNegativeButton("取消",null).show();}
    private int dp(float value){return Ui.dp(this,value);}
    private void populate(){String key=search.getText().toString().toLowerCase(Locale.ROOT);rows.clear();counts.clear();ArrayList<Item> filtered=new ArrayList<>();for(Item item:items)if(item.entry.label.toLowerCase(Locale.ROOT).contains(key)||item.entry.pkg.toLowerCase(Locale.ROOT).contains(key)){filtered.add(item);counts.merge(item.group,1,Integer::sum);}String group=null;for(Item item:filtered){if(!item.group.equals(group)){group=item.group;rows.add(group);}if(!collapsed.contains(group))rows.add(item);}adapter.notifyDataSetChanged();}
}
